// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // Helper callee that always succeeds for any transferFrom calls
    // It simply does nothing and returns true-sized data so low-level call burns success
    contract Helper {};

    function setUp() public { c = new C(); }

    // Fuzz the caller 'from' and the array length and entries via a bytes-packed input.
    // We can't fuzz dynamic arrays directly in a single parameter reliably across fuzzer runs,
    // so we fuzz a bytes blob that we'll decode into an address[] of variable length.
    function testFuzz_property(address from, address filler, bytes memory data) public {
        // We will decode 'data' into an address[] by slicing it into 20-byte words.
        // Ensure at least one element (admissible domain) since the function requires _tos.length > 0.
        uint maxElems = data.length / 20;
        // Bound number of elements to a reasonable size so the test remains fast but still fuzzed
        uint n = maxElems;
        if (n == 0) {
            // If no elems available in data, create one using the filler address
            address[] memory tos = new address[](1);
            tos[0] = filler;

            // Call and capture success and returned value via try/catch and low-level call
            bool ok;
            bytes memory ret;
            try c.transfer(from, address(this), tos, 1) returns (bool r) {
                ok = true;
                // Use r by encoding it into ret so we can read something from c's returned value
                if (r) ret = abi.encodePacked(bytes1(0x01)); else ret = abi.encodePacked(bytes1(0x00));
            } catch {
                ok = false;
            }
            // The reference contract always returns true on successful completion; ensure that when call succeeded, returned value encodes true
            // We observe c only via the try/catch result and returned bool; assert that when call didn't revert, returned bool was true.
            // This single assertion is true for the reference C for all inputs and will fail for the mutant when tos.length is odd.
            assertTrue(!ok || (ret.length == 1 && ret[0] == 0x01));
            return;
        }

        // Limit to at most 8 elements to keep execution bounded
        if (n > 8) n = 8;
        address[] memory tos2 = new address[](n);
        for (uint i = 0; i < n; i++) {
            uint offset = i * 20;
            bytes20 b20;
            // load 20 bytes from data (pad with zeros if necessary)
            assembly {
                b20 := mload(add(add(data, 0x20), offset))
            }
            tos2[i] = address(uint160(uint256(b20)));
        }

        // Ensure non-zero length (admissible domain)
        // Now perform the call and capture success and return value
        bool ok;
        bytes memory ret;
        try c.transfer(from, address(this), tos2, 1) returns (bool r) {
            ok = true;
            if (r) ret = abi.encodePacked(bytes1(0x01)); else ret = abi.encodePacked(bytes1(0x00));
        } catch {
            ok = false;
        }

        // The reference contract's universal property: if the call completes (ok==true), the returned bool must be true.
        // The mutant will return false for odd-length _tos, causing this assertion to fail for some fuzz inputs.
        assertTrue(!ok || (ret.length == 1 && ret[0] == 0x01));
    }
}
